  );
};

export default Header;

src/components/Login.js.content:
import React, { useState } from 'react';
import { useAuth } from '../services/AuthContext';

const Login = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const { login } = useAuth();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    if (!username.trim() || !password.trim()) {
      setError('Please enter both username and password');
      setIsLoading(false);
      return;
    }

    try {
      const result = await login(username.trim(), password);
      if (!result.success) {
        setError(result.error || 'Login failed');
      }
    } catch (error) {
      setError('An error occurred. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex items-center justify-center min-h-96">
      <div className="card w-full max-w-md slide-up">
        <div className="card-body p-6">
          <div className="text-center mb-6">
            <img 
              src="/icons/logo.png" 
              alt="Shawarma Boss Logo" 
              className="w-20 h-20 mx-auto mb-4 rounded"
              onError={(e) => {
                e.target.style.display = 'none';
              }}
            />
            <h2 className="text-xl font-bold text-danger">Shawarma Boss POS</h2>
            <p className="text-muted text-sm mt-1">Modern MERN Stack Point of Sale</p>
          </div>

          <form onSubmit={handleSubmit}>
            <div className="mb-4">
              <label className="block text-sm font-medium mb-2">Username</label>
              <input
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="form-control"
                placeholder="Enter username"
                disabled={isLoading}
                autoComplete="username"
              />
            </div>

            <div className="mb-4">
              <label className="block text-sm font-medium mb-2">Password</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="form-control"
                placeholder="Enter password"
                disabled={isLoading}
                autoComplete="current-password"
              />
            </div>

            {error && (
              <div className="text-danger text-sm mb-4 p-2 bg-red-50 border border-red-200 rounded">
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              className="btn btn-danger w-full flex items-center justify-center"
            >
              {isLoading ? (
                <div className="spinner w-4 h-4"></div>
              ) : (
                'Login'
              )}
            </button>
          </form>

          <div className="mt-6 text-center text-sm text-muted">
            <div className="mb-2">
              <strong>Demo Accounts:</strong>
            </div>
            <div className="space-y-1">
              <div>Admin: <code>admin</code> / <code>admin123</code></div>
              <div>Staff: <code>staff1</code> / <code>staff123</code></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

src/components/MenuGrid.js.content:
import React, { useState } from 'react';
import { useCart } from '../services/CartContext';

const MenuGrid = ({ menu }) => {
  const { addToCart } = useCart();
  const [quantities, setQuantities] = useState({});

  const handleQuantityChange = (itemId, quantity) => {
    setQuantities(prev => ({
      ...prev,
      [itemId]: Math.max(1, parseInt(quantity) || 1)
    }));
  };

  const handleAddToCart = (item) => {
    const quantity = quantities[item.id] || 1;
    if (item.stock < quantity) {
      alert(`Not enough stock! Only ${item.stock} available.`);
      return;
    }
    addToCart(item, quantity);
    // Reset quantity to 1 after adding
    setQuantities(prev => ({
      ...prev,
      [item.id]: 1
    }));
  };

  const getStockStatus = (stock) => {
    if (stock === 0) return { text: 'Out of Stock', class: 'stock-out' };
    if (stock <= 5) return { text: `Low Stock (${stock})`, class: 'stock-low' };
    return { text: `In Stock (${stock})`, class: 'text-success' };
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
      {menu.map((item) => {
        const stockStatus = getStockStatus(item.stock);
        const quantity = quantities[item.id] || 1;

        return (
          <div key={item.id} className="card menu-card">
            <div className="card-body">
              <div className="flex justify-between items-start mb-2">
                <h5 className="font-bold text-lg">{item.name}</h5>
                <span className="text-danger font-bold text-lg">
                  GHS {parseFloat(item.price || 0).toFixed(2)}
                </span>
              </div>

              <div className={`text-sm mb-3 ${stockStatus.class}`}>
                {stockStatus.text}
              </div>

              <div className="flex gap-2 items-center">
                <input
                  type="number"
                  min="1"
                  max={item.stock}
                  value={quantity}
                  onChange={(e) => handleQuantityChange(item.id, e.target.value)}
                  className="form-control w-20 text-center"
                  disabled={item.stock === 0}
                />
                <button
                  onClick={() => handleAddToCart(item)}
                  disabled={item.stock === 0}
                  className="btn btn-danger flex-1"
                >
                  {item.stock === 0 ? 'Out of Stock' : 'Add to Cart'}
                </button>
              </div>
            </div>
          </div>
        );
      })}

      {menu.length === 0 && (
        <div className="col-span-full text-center py-8 text-muted">
          No menu items available
        </div>
      )}
    </div>
  );
};

export default MenuGrid;

src/components/POS.js.content:
import React, { useState, useEffect } from 'react';
import { useAuth } from '../services/AuthContext';
import { useCart } from '../services/CartContext';
import { getMenu, createOrder, updateMenuStock } from '../services/api';
import MenuGrid from './MenuGrid';
import Cart from './Cart';
import OrderModal from './OrderModal';

const POS = () => {
  const { user } = useAuth();
  const { cartItems, clearCart, getCartTotal } = useCart();
  const [menu, setMenu] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [showOrderModal, setShowOrderModal] = useState(false);
  const [recentOrders, setRecentOrders] = useState([]);

  useEffect(() => {
    loadMenu();
    loadRecentOrders();
  }, []);

  const loadMenu = async () => {
    try {
      setIsLoading(true);
      const menuData = await getMenu();
      setMenu(menuData);
      setError('');
    } catch (error) {
      console.error('Error loading menu:', error);
      setError('Failed to load menu. Please refresh the page.');
    } finally {
      setIsLoading(false);
    }
  };

  const loadRecentOrders = () => {
    const stored = localStorage.getItem('shawarma_boss_recent_orders');
    if (stored) {
      try {
        setRecentOrders(JSON.parse(stored));
      } catch (error) {
        console.error('Error loading recent orders:', error);
      }
    }
  };

  const handleConfirmOrder = async () => {
    if (cartItems.length === 0) {
      alert('Cart is empty!');
      return;
    }

    const order = {
      id: 'order-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
      user: user.username,
      staff: user.username,
      timestamp: new Date().toISOString(),
      items: cartItems,
      total: getCartTotal(),
      status: 'completed'
    };

    try {
      // Save order to backend
      await createOrder(order);

      // Update stock for each item
      for (const item of cartItems) {
        const menuItem = menu.find(m => m.id === item.id);
        if (menuItem && menuItem.stock >= item.quantity) {
          await updateMenuStock(item.id, menuItem.stock - item.quantity);
        }
      }

      // Update local menu state
      setMenu(prevMenu =>
        prevMenu.map(menuItem => {
          const cartItem = cartItems.find(item => item.id === menuItem.id);
          if (cartItem) {
            return {
              ...menuItem,
              stock: Math.max(0, menuItem.stock - cartItem.quantity)
            };
          }
          return menuItem;
        })
      );

      // Save to recent orders
      const newRecentOrders = [order, ...recentOrders.slice(0, 4)];
      setRecentOrders(newRecentOrders);
      localStorage.setItem('shawarma_boss_recent_orders', JSON.stringify(newRecentOrders));

      // Show order modal
      setShowOrderModal(true);

      // Clear cart
      clearCart();
    } catch (error) {
      console.error('Error creating order:', error);
      alert('Failed to create order. Please try again.');
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <div className="spinner"></div>
        <span className="ml-2">Loading menu...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="card">
        <div className="card-body text-center">
          <div className="text-danger mb-4">{error}</div>
          <button 
            onClick={loadMenu}
            className="btn btn-danger"
          >
            Retry
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="fade-in">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Menu Section */}
        <div className="lg:col-span-2">
          <div className="card">
            <div className="card-body">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-danger">Menu</h3>
                <button
                  onClick={loadMenu}
                  className="btn btn-outline-danger btn-sm"
                >
                  Refresh Menu
                </button>
              </div>
              <MenuGrid menu={menu} />
            </div>
          </div>
        </div>

        {/* Cart & Recent Orders Section */}
        <div className="space-y-6">
          <Cart onConfirmOrder={handleConfirmOrder} />

          {/* Recent Orders */}
          <div className="card">
            <div className="card-body">
              <h4 className="font-bold text-danger mb-4">Recent Orders</h4>
              {recentOrders.length === 0 ? (
                <p className="text-muted text-sm">No recent orders</p>
              ) : (
                <div className="space-y-2">
                  {recentOrders.map((order) => (
                    <div key={order.id} className="text-sm p-2 bg-gray-50 rounded">
                      <div className="flex justify-between items-center">
                        <span className="font-medium">Order #{order.id.slice(-6)}</span>
                        <span className="text-success font-bold">GHS {order.total.toFixed(2)}</span>
                      </div>
                      <div className="text-muted text-xs mt-1">
                        {new Date(order.timestamp).toLocaleString()}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Order Success Modal */}
      {showOrderModal && (
        <OrderModal
          order={recentOrders[0]}
          onClose={() => setShowOrderModal(false)}
        />
      )}
    </div>
  );
};

export default POS;

